sys_aw_page.page_definition:
{
  "layout": {
    "type": "container",
    "children": [
      {
        "type": "header",
        "title": "📈 New Trade Entry",
        "subtitle": "Enter details for a new trading position",
        "actions": [
          {
            "type": "button",
            "label": "Save Trade",
            "variant": "primary",
            "action": "save_record"
          },
          {
            "type": "button",
            "label": "Clear Form",
            "variant": "secondary",
            "action": "clear_form"
          }
        ]
      },
      {
        "type": "form",
        "table": "x_snc_trade_mana_0_trade_book",
        "fields": [
          {
            "name": "stock_name",
            "label": "Stock Name",
            "type": "string",
            "required": true,
            "placeholder": "e.g., Apple Inc. (AAPL)",
            "help": "Enter the full stock name with ticker symbol"
          },
          {
            "name": "buying_price",
            "label": "Buying Price ($)",
            "type": "string",
            "required": true,
            "placeholder": "e.g., 150.25",
            "help": "Enter the purchase price per share"
          },
          {
            "name": "stop_loss",
            "label": "Stop Loss ($)",
            "type": "string",
            "required": true,
            "placeholder": "e.g., 140.00",
            "help": "Enter the stop loss price for risk management"
          },
          {
            "name": "date",
            "label": "Trade Date",
            "type": "glide_date",
            "required": true,
            "default": "today",
            "help": "Select the date when the trade was executed"
          }
        ],
        "layout": "two_column"
      },
      {
        "type": "info_panel",
        "title": "💡 Trading Tips",
        "content": [
          {
            "type": "text",
            "value": "• Always set a stop loss to manage risk"
          },
          {
            "type": "text",
            "value": "• Research the stock thoroughly before investing"
          },
          {
            "type": "text",
            "value": "• Diversify your portfolio across different sectors"
          },
          {
            "type": "text",
            "value": "• Keep track of all your trades for tax purposes"
          }
        ]
      }
    ]
  }
}
